private void Rap_FormatShitjeA5Gani_2kopje_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  this.Detail.Controls.Add(CreateXRTable());
            System.Data.DataTable dt = ((System.Data.DataSet)(this.DataSource)).Tables[0];

            trupi.Clear();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                object kodi = dt.Rows[i]["KODI"]; 
                object pershkrimi = dt.Rows[i]["PERSHKRIMI"]; 
                object njesia = dt.Rows[i]["PERSHKRIMNJESIA"];
                object sasia = dt.Rows[i]["SASIA"];
                object cmimi = Convert.ToDouble(Convert.ToDouble(dt.Rows[i]["VLEFTAMETVSH"]) / (1 - Convert.ToDouble(dt.Rows[i]["ZBRITJEPERQ"]) / 100) / Convert.ToDouble(dt.Rows[i]["SASIA"]));
                object vleraMeTvsh = dt.Rows[i]["VLEFTAMETVSH"];
                object[] obj = new object[10];

                obj[0] = (i + 1).ToString();
                obj[1] = kodi;
                obj[2] = pershkrimi;
                obj[3] = njesia;
                obj[4] = sasia;
                obj[5] = cmimi;
                obj[6] = vleraMeTvsh;

                trupi.Add(obj);
}

var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]); 

  AlphaWebReports.raporteUtil.shfaqLlogariteBankare( parametraRaporti.IdNdermarrje, parametraRaporti.IdPerdoruesi, null, null, distancaLartesi,
koordinataY, koordinataX, koordinataLlogariX, "Times New Roman", 10.2F, System.Drawing.FontStyle.Regular, Color.Black,
 100F, 20F, 663.23F, 20F, 0);
}

  private void shtoRreshtatNeTabele(XRTable xrTable2)
        {
            int i = 0;
            if (trupi.Count > 0)
            {
                for (int j = xrTable2.Rows.Count - 1; j >= 1; j--)
                {
                    xrTable2.Rows.RemoveAt(j);
                }
                Font arial = new Font("Arial", 9.75F, FontStyle.Regular);
                PaddingInfo padding = new PaddingInfo(2, 2, 0, 0);
                foreach (object[] obj in trupi)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 20f;

                    XRTableCell nr = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(22.24f, "" , obj[0].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, BorderSide.Bottom, padding);
                    rr.Cells.Add(nr);

                    XRTableCell kodi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(105.13f, "" , obj[1].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, BorderSide.Bottom, padding);
                    rr.Cells.Add(kodi);

                    XRTableCell pershkrimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(190.32f, "" , obj[2].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, BorderSide.Bottom, padding);
                    rr.Cells.Add(pershkrimi);

                    XRTableCell njesia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(44f, "" , obj[3].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, BorderSide.Bottom, padding);
                    rr.Cells.Add(njesia);

                    XRTableCell sasia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(49.76f, "" , String.Format("{0:n3}", obj[4]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, BorderSide.Bottom, padding);
                    rr.Cells.Add(sasia);

                    XRTableCell cmimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(67.29f, "" , String.Format("{0:#,#.00}", obj[5]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, BorderSide.Bottom, padding);
                    rr.Cells.Add(cmimi);

                    XRTableCell vleraMeTvsh = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(70.26f, "" , String.Format("{0:#,#.00}", obj[6]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, BorderSide.Bottom, padding);
                    rr.Cells.Add(vleraMeTvsh);

                    xrTable2.Rows.Insert((i + 1), rr);
                    i++;
                }
            }
        }


    private XRTable CreateXRTable()
        {
            int i = 0;
            XRTable table = new XRTable();
            table.Size = new Size(650, 20);//.HeightF = 25f;
            table.BeginInit();
            //table.WidthF = 650f;
            table.LocationF = new DevExpress.Utils.PointFloat(0F, 0F);
            if (trupi.Count > 0)
            {

                for (int j = table.Rows.Count - 1; j >= 1; j--)
                {
                    table.Rows.RemoveAt(j);
                }
                foreach (object[] obj in trupi)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 20f;
                    //Cell NR
                    XRTableCell nr = new XRTableCell();
                    nr.WidthF = 22.24f;
                    nr.Name = "nr" ;//+ i.ToString();
                    nr.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    nr.Text = obj[0].ToString();
                    nr.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    nr.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleCenter;
                    nr.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    nr.BorderColor = System.Drawing.Color.Silver;
                    nr.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(nr);
                    //Cell kodi
                    XRTableCell kodi = new XRTableCell();
                    kodi.WidthF = 105.13f;
                    kodi.Name = "kodi";// + i.ToString();
                    kodi.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    kodi.Text = obj[1].ToString();
                    kodi.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    kodi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    kodi.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    kodi.BorderColor = System.Drawing.Color.Silver;
                    kodi.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(kodi);
                    //Cell pershkrimi
                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.WidthF = 190.32f;
                    pershkrimi.Name = "pershkrimi" ;//+ i.ToString();
                    pershkrimi.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    pershkrimi.Text = obj[2].ToString();
                    pershkrimi.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    pershkrimi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    pershkrimi.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    pershkrimi.BorderColor = System.Drawing.Color.Silver;
                    pershkrimi.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(pershkrimi);
                    //Cell njesia
                    XRTableCell njesia = new XRTableCell();
                    njesia.WidthF = 44f;
                    njesia.Name = "njesia";// + i.ToString();
                    njesia.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    njesia.Text = obj[3].ToString();
                    njesia.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    njesia.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    njesia.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    njesia.BorderColor = System.Drawing.Color.Silver;
                    njesia.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(njesia);
                    //Cell sasia
                    XRTableCell sasia = new XRTableCell();
                    sasia.WidthF = 49.76f;
                    sasia.Name = "sasia" ;//+ i.ToString();
                    sasia.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    sasia.Text = String.Format("{0:n3}", obj[4]);
                    sasia.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    sasia.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    sasia.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    sasia.BorderColor = System.Drawing.Color.Silver;
                    sasia.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(sasia);
                    //Cell cmimi
                    XRTableCell cmimi = new XRTableCell();
                    cmimi.WidthF = 67.29f;
                    cmimi.Name = "cmimi" ;//+ i.ToString();
                    cmimi.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    cmimi.Text = String.Format("{0:#,#.00}", obj[5]);
                    cmimi.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    cmimi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    cmimi.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    cmimi.BorderColor = System.Drawing.Color.Silver;
                    cmimi.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(cmimi);
                    //Cell vleraMeTvsh
                    XRTableCell vleraMeTvsh = new XRTableCell();
                    vleraMeTvsh.WidthF = 70.26f;
                    vleraMeTvsh.Name = "vleraMeTvsh" ;//+ i.ToString();
                    vleraMeTvsh.Font = new System.Drawing.Font("Arial", 9.75F, System.Drawing.FontStyle.Regular);
                    vleraMeTvsh.Text = String.Format("{0:#,#.00}", obj[6]);
                    vleraMeTvsh.Padding = new DevExpress.XtraPrinting.PaddingInfo(2, 2, 0, 0);
                    vleraMeTvsh.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    vleraMeTvsh.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    vleraMeTvsh.BorderColor = System.Drawing.Color.Silver;
                    vleraMeTvsh.BackColor = System.Drawing.Color.Transparent;
                    rr.Cells.Add(vleraMeTvsh);
                    table.Rows.Add(rr);
                    i++;
                }
                table.EndInit();
            }
            return table;
        }
